INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Santé & Médecine', 'Un secteur régi par la rigueur et l''humain. Tu passes de longues années d''études, mais tu repars avec un métier stable, respecté et profondément utile. . etudes 1 à 11 ans après le bac . salaire 1 600 – 4 500 € . debouches Très stables, très demandés . rythme Astreintes, week-ends, gardes . evolution Généraliste → spécialisation → cadre . metiers Médecin généraliste 6 ans après le bac 2 500 – 4 500 € / mois Chirurgien·ne 8 à 11 ans après le bac 4 000 – 8 000 € / mois Infirmier·ère 3 ans (IFSI) + concours 1 800 – 2 600 € / mois Masseur-kinésithérapeute 5 ans après le bac 1 900 – 3 200 € / mois Biologiste médical 6 ans (biologie médicale) 2 800 – 5 000 € / mois Chirurgien-dentiste 6 ans après le bac 3 000 – 6 000 € / mois Pharmacien·ne 6 ans après le bac 2 500 – 4 000 € / mois Sage-femme 5 ans après le bac 2 200 – 3 500 € / mois Aide-soignant·e 1 an (débouché rapide) 1 600 – 2 100 € / mois Cadre de santé / directeur·rice de clinique Diplôme + expérience 3 000 – 5 500 € / mois', 'secteur', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'e36c6de61a97e0233b41fe569dec66fb') ON CONFLICT (content_hash) DO NOTHING;
