INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Royaume-Uni', 'Anglais (IELTS / TOEFL) . Licence 3 ans · Master 1 an . ≈ 9 000 – 25 000 £ / an . Candidature via UCAS jusqu''en janvier . Cours en anglais, 20 h/semaine de travail autorisé pendant les études. . universites : University of Oxford, University of Cambridge, Imperial College London, University College London (UCL), University of Edinburgh, University of Manchester, King''s College London, University of Bristol, University of Warwick, University of Glasgow', 'pays', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'a2419e7694f8c65f606a5fc5df2f77ff') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Canada', 'Anglais ou français (IELTS / TEF) . Baccalauréat 3-4 ans · Master 1-2 ans . ≈ 15 000 – 40 000 $CA / an . 2 entrées : septembre et janvier . Permis d''études, puis permis de travail post-diplôme de 1 à 3 ans. . universites : University of Toronto, McGill University, University of British Columbia, University of Waterloo, Université de Montréal, McMaster University, University of Alberta, Université Laval, University of Ottawa, Simon Fraser University', 'pays', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'a49d2365e63bf5ea56607bee8d539d15') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('États-Unis', 'Anglais (TOEFL / IELTS / SAT) . Bachelor 4 ans · Master 1-2 ans . ≈ 25 000 – 60 000 $ / an . Candidature directe : octobre à janvier . Bourses au mérite (merit scholarships) très développées. . universites : Massachusetts Institute of Technology (MIT), Stanford University, Harvard University, University of California, Berkeley, Columbia University, Cornell University, University of California, Los Angeles, University of Michigan, University of Illinois Urbana-Champaign, Georgia Institute of Technology, Yale University, Princeton University, California Institute of Technology, New York University, University of Washington, Purdue University, Duke University', 'pays', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '23cc9585f1b835723dca3ff7f74280ec') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Allemagne', 'Allemand (TestDaF) ou anglais . Licence 3 ans · Master 2 ans . Gratuit à ≈ 3 000 € / an . Candidature via uni-assist . Frais de scolarité quasi nuls dans le public, DAAD pour les bourses. . universites : Technische Universität München, Ludwig-Maximilians-Universität München, Universität Heidelberg, RWTH Aachen University, Karlsruher Institut für Technologie (KIT), Humboldt-Universität zu Berlin, Freie Universität Berlin, Technische Universität Berlin, Universität Stuttgart, Universität Leipzig', 'pays', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '1fdb20ef4093e006d74a10e2b8b395b4') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Devenir médecin — le parcours complet', 'Parcours . Maturité / bac scientifique (SVT, maths, physique) . 1re année : PASS (60 % santé) ou LAS (licence avec option santé) . Cycle clinique : 2e à 6e année, stages en hôpital et en ville . Stage d''OPA (1 an) obligatoire pour signer sa thèse . Médecine générale : 3 ans de plus · Spécialité : 3 à 5 ans de plus . Titre de docteur en médecine, inscrit à l''Ordre national', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'dec07b3610d57f0e1a45dbcb7962d3cd') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('PASS ou LAS : quelle différence ?', 'Parcours . PASS : 60 % santé + 40 % mineur, la voie classique « prépa santé » . LAS : licence de 3 ans, 50 % de cours de santé, on peut se réorienter . Les deux donnent accès au même concours (conduite en 2e année) . Mieux vaut choisir la LAS si tu veux garder une porte de sortie (biologie, chimie, maths) . Critère de réussite : régularité, cartes de révision, annales des années précédentes', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '127edaed09496afd77abd1727f0688d2') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('L''internat (ECN et spécialité)', 'Parcours . Après la 6e année : les ECN (épreuves classantes nationales) . Le classement national choisit ta spécialité ET ta ville . Durée de l''internat : 3 à 5 ans selon la spécialité . Pendant l''internat : salaire net ≈ 2 000 – 3 500 €/mois, rythme de gardes soutenu . La chirurgie et l''anesthésie sont les plus longues, la dermatologie et l''ophtalmologie les plus demandées', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '0d0d15c3aa9f86805dc32ef5f81a1154') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Combien d''années pour être médecin ?', 'Parcours . Médecin généraliste : 6 ans après le bac . La plupart des spécialités : 9 à 11 ans . Chirurgie et quelques subspécialités : 11 à 14 ans . Chirurgien-dentiste : 6 ans · Pharmacien : 6 ans · Sage-femme : 6 ans . Kinésithérapeute : 5 ans · Infirmier : 3 ans · Aide-soignant : 2 ans', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'ce1ea62c7e704861caba389d5c54abd6') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Études de médecine à l''étranger', 'Parcours . Europe de l''Est (Pologne, Roumanie, Bulgarie, Hongrie) : 5 000 – 12 000 €/an en anglais . Afrique francophone (Maroc, Tunisie, Algérie) : 1 000 – 5 000 €/an, en français . Le bonus : coût doux et admission par dossier ou examen (YÖS) . Le revers : retour en France = passer les équivalences (très difficile) . À vérifier avant de partir : reconnaissance du diplôme par le Conseil de l''Ordre', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '427bdb70be9a5c4e22fc618f764339aa') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Combien coûtent les études de médecine ?', 'Parcours . France (public) : frais universitaires ≈ 170 à 400 €/an . France (privé : Île-de-France) : ≈ 5 000 – 15 000 €/an . Étranger public : 500 à 5 000 €/an · privé : 10 000 à 40 000 $/an . Aides possibles : bourse sur critères sociaux, CROUS, bourses régionales . Le chiffre important : la vie à côté (loyer, transport) coûte souvent plus que les cours', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '93f76e6a0d27a69b2e152349fb4546ca') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Notes pour entrer en médecine', 'Parcours . Passer le bac scientifique solide (SVT et physique haut de gamme) . Pour le parcours direct en France : il n''y a plus de numerus clausus national, mais des capacités d''accueil limitées . À l''étranger : moyenne du bac souvent demandée (12 à 14/20), parfois un test . Conseil : vise les annales, ce sont elles qui décident — pas le classement de ton lycée', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '3f9d9c458c84dc425882085b29fd739b') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Travailler à l''hôpital ou en libéral ?', 'Parcours . Hôpital : salaire fixe, gardes, équipe, avantages (logement de fonction possible) . Libéral : indépendance et revenus plus élevés, mais gérer sa patientèle et son cabinet . La majorité des généralistes est « conventionnée secteur 1 » (tarif fixé par l''Assurance Maladie) . Secteur 2 : honoraires plus élevés, reste à charge pour le patient . Un parcours classique : hôpital puis cabinet, ou les deux en ville', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'dcf1c90932c48e399f496f1be4eeddca') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Médecin généraliste', 'Spécialité . Traite tout : infection, maladie chronique, suivi, prévention . Études : 6 ans après le bac (dont le stage d''OPA) . Salaire : ≈ 2 500 – 5 500 € net/mois en début de carrière . Quotidien : 25 à 35 patients par jour, à domicile pour les fragiles . C''est la spécialité la plus facile d''accès et la plus demandée pour les services publics', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '551a18e6c19607dfcd8693a71ace3612') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Cardiologue', 'Spécialité . Soigne les maladies du cœur, des artères et du système circulatoire . Études : 9 à 11 ans après le bac . Salaire : ≈ 4 000 – 9 000 € net/mois . Quotidien : consultations, ECG, échographies, cathétérismes, urgences de crise cardiaque', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '9428be96b87aed64d947f9801270932e') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Chirurgien', 'Spécialité . Opère : abdomen, cœur, cerveau, os, organes… . Études : 11 à 14 ans après le bac (dont 5 ans d''internat) . Salaire : ≈ 5 000 – 12 000 € net/mois . Quotidien : bloc opératoire, gardes, consultation avant et après l''opération . Le plus long des parcours — mais celui qui recrute partout dans le monde', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '21d43962f7b15a0f00b33a47a03b06a1') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Pédiatre', 'Spécialité . Soigne les enfants de la naissance à 18 ans . Études : 6 ans de médecine puis 3 ans de pédiatrie . Salaire : ≈ 3 500 – 7 000 € net/mois . Quotidien : vaccins, croissance, infections, échanges avec les parents', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '71b0882b3a7f6ad2073e66e83089a103') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Neurologue / neurochirurgien', 'Spécialité . Le neurologue traite le cerveau, la moelle épinière et les nerfs . Le neurochirurgien opère : tumeurs, anévrismes, hernies discales . Études : 11 à 14 ans après le bac . Salaire : neurologue ≈ 4 500 – 8 000 € · neurochirurgien ≈ 6 000 – 15 000 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '592e66b6078fd788bde105da5a39193d') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Radiologue', 'Spécialité . Lit et interprète les radios, scanners, IRM et échographies . Études : 11 ans après le bac . Salaire : ≈ 4 500 – 9 000 € net/mois . Quotidien : lecture d''images en salle sombre, ponctions guidées, peu de gardes', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '874712999b938ed677aeab236cf2aaaa') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Anesthésiste-réanimateur', 'Spécialité . Anesthésie avant l''opération et réanimation des patients graves . Études : 11 ans après le bac . Salaire : ≈ 5 000 – 11 000 € net/mois . Point fort : c''est une des spécialités les plus demandées et les mieux payées', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'e5bd683a7f60538643ecef5d546728a0') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Dermatologue', 'Spécialité . Traite les maladies de la peau, des cheveux et des ongles . Études : 11 ans après le bac . Salaire : ≈ 4 000 – 9 000 € net/mois . Quotidien : consultations, petites chirurgies, biopsies', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '1a4b220457e104125a55d8d015e5383e') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Gynécologue-obstétricien', 'Spécialité . Suit les grossesses et traite les maladies de la femme . Études : 11 ans après le bac . Salaire : ≈ 4 000 – 9 000 € net/mois . Quotidien : consultations, échographies, accouchements de jour comme de nuit', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '76b37048533e1270c328dd321b9b6a69') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Ophtalmologue', 'Spécialité . Soigne les yeux : vue, cataracte, glaucome, rétine . Études : 11 ans après le bac . Salaire : ≈ 4 500 – 10 000 € net/mois . Quotidien : examens de la vue, chirurgie laser, peu de gardes', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '91a936fe4efc63a95b2d1849a06c13bf') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('ORL (oto-rhino-laryngologiste)', 'Spécialité . Soigne l''ouïe, le nez, les sinus, la gorge et le larynx . Études : 11 ans après le bac . Salaire : ≈ 4 000 – 9 000 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '1d0a29f4604071dd536349ae3a5f8d56') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Psychiatre', 'Spécialité . Soigne les troubles psychiques : dépression, anxiété, schizophrénie… . Études : 6 ans de médecine puis 5 ans de psychiatrie . Salaire : ≈ 4 000 – 8 000 € net/mois . À ne pas confondre : le psychologue n''est pas médecin et ne prescrit pas . Peut exercer à l''hôpital, en cabinet ou en addictologie', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '09e469071e1f4336ff54bbac3ad5779f') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Oncologue', 'Spécialité . Traite les cancers : chimiothérapie, ciblage, immuno-oncologie . Études : 11 ans puis une formation complémentaire en cancérologie . Salaire : ≈ 4 500 – 10 000 € net/mois . Le domaine où la recherche avance le plus vite (essais cliniques)', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '6ccbed10ede3e672b8fdb1f1b6ea348e') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Urgentiste', 'Spécialité . Prend en charge les urgences vitales, 24 h/24 . Études : 6 ans de médecine puis 4 ans d''urgence . Salaire : ≈ 5 000 – 12 000 € net/mois . Quotidien : SAMU, salle d''accueil des urgences, gestes de réanimation', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '9bfdee65552df23cf119352c40d5d32d') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Gastro-entérologue', 'Spécialité . Traite l''appareil digestif : estomac, intestins, foie, pancréas . Études : 11 ans après le bac . Salaire : ≈ 4 500 – 9 000 € net/mois . Quotidien : consultations, endoscopies digestives', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'bd68d1ed72c24c606667eea114848cab') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Traumatologue / chirurgien orthopédiste', 'Spécialité . Traite les os, les articulations, les entorses et les douleurs de dos . Études : 11 ans après le bac . Salaire : ≈ 4 500 – 10 000 € net/mois . Partout : cliniques du sport, hôpitaux, cabinets', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '7583f735b35240ab3e1d2e4bc930359d') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Urologue', 'Spécialité . Traite l''appareil urinaire et, chez l''homme, la prostate . Études : 11 ans après le bac . Salaire : ≈ 4 500 – 9 000 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '3806b61633a1c708e5d2a322d76bfed3') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Pneumologue', 'Spécialité . Traite les maladies respiratoires : asthme, BPCO, tabac . Études : 11 ans après le bac . Salaire : ≈ 4 500 – 8 500 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'e8886278e437ef03db5d49ea023992ce') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Sage-femme', 'Santé . Accompagne la grossesse, pratique les accouchements et le suivi post-partum . Études : 2e cycle de 3 ans après la 1re année de santé (bac + 6) . Salaire : ≈ 3 000 – 5 500 € net/mois . Exercice : maternités, cabinets libéraux, communautés de pratique', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '079053ea2e66b1981fe1c72ee49e4915') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Infirmier·ère', 'Santé . Soigne, administre les traitements et accompagne les patients . Études : 3 ans (IFAS/IFIK) après le bac, concours d''entrée . Salaire : ≈ 1 900 – 3 200 € net/mois . Spécialités possibles : réanimation, bloc, DPAD, psychiatrie, pédiatrie . Demande : le métier le plus recruté de toute la santé, en France comme à l''étranger', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '3fda07b3308a8116e10c98e01a7e22b8') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Aide-soignant', 'Santé . Aide les patients à la toilette, aux repas, à la mobilisation . Études : 2 ans (Diplôme d''État) . Salaire : ≈ 1 700 – 2 500 € net/mois . Points forts : accès rapide au métier, passerelle vers l''infirmier', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'd5d08081a3a027991f46cc60c8903401') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Chirurgien-dentiste', 'Santé . Soigne les dents : caries, implants, prothèses, orthodontie . Études : 6 ans après le bac (2e cycle de 3 ans) . Salaire : ≈ 3 000 – 7 000 € net/mois, plus en libéral . Le métier de santé libéral le plus accessible', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '8242b81c54d8d9586d0b01d88e4c8220') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Pharmacien', 'Santé . Délivre les médicaments, conseille, suit les pathologies chroniques . Études : 6 ans après le bac (3e cycle) . Salaire : ≈ 3 000 – 5 500 € net/mois en officine . Options : hôpital, industrie, recherche, officine en groupe', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'c4bf0f3770e0510e641896e6de567985') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Kinésithérapeute', 'Santé . Rééduque après une blessure ou une opération, soigne les douleurs . Études : 5 ans après le bac (IFMK, concours) . Salaire : ≈ 2 500 – 4 500 € net/mois . Exercice : cabinet, hôpital, domicile, clubs sportifs', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '449a8e47b236a8222d0d1d1a4f003f2d') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Manipulateur en électroradiologie', 'Santé . Realise les examens d''imagerie (radios, scanners, IRM) . Études : 3 ans après le bac (Diplôme d''État) . Salaire : ≈ 2 200 – 3 500 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '447e18c3cacc8dd7365695362fa8d8ae') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Orthoptiste', 'Santé . Réévalue et rééduque les troubles de la vision . Études : 3 ans après le bac . Salaire : ≈ 2 300 – 3 500 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '1a83958171cd1df68c65eccfe12487ac') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Ambulancier', 'Santé . Transporte et assiste les patients en ambulance . Études : DAE (1 an) + possibilité de devenir infirmier . Salaire : ≈ 1 800 – 2 800 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '2a3f4e40d45169d3dd05b39bb087a733') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Psychomotricien', 'Santé . Accompagne les troubles du mouvement et du comportement . Études : 3 ans après le bac . Salaire : ≈ 2 000 – 3 000 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'ce5645e057c31f3ba11d4e34370f66bd') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Podologue', 'Santé . Soigne les pieds : cors, ongles, semelles, troubles de la marche . Études : 3 ans après le bac (Diplôme d''État) . Salaire : ≈ 2 500 – 4 500 € net/mois en libéral', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'a99e99bd19b73f981532b4d883529750') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Diététicien', 'Santé . Construit des équilibres alimentaires adaptés à chaque patient . Études : Bac+3 (BTS ou DUT) . Salaire : ≈ 2 200 – 3 500 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'a7cc5c463938de01050e1b60f09d1ca0') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Technicien de laboratoire', 'Santé . Fait les analyses biologiques (sang, urines, tests) . Études : Bac+3 (DUT/BUT) . Salaire : ≈ 2 100 – 3 200 € net/mois', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'f86ee80c14e30c0b1a6a1f20431bdc04') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Symptômes : que faire ?', 'Soin . Pégase ne pose PAS de diagnostic : pour un symptôme, consulte un médecin . Urgences vitales : 15 (SAMU) ou 112 en Europe · pompiers : 18 · Europe : 112 . Conseils simples : hydrate-toi, repose-toi, note l''apparition et la durée . En cas de douleur thoracique, malaise, essoufflement : appelle le 15 sans attendre', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '174b2650526455c912b9f345004bb5a0') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Vaccination : les rappels', 'Soin . Le rappel de la rougeole à 16-18 mois est obligatoire en France . HPV (papillomavirus) : recommandé vers 11-14 ans, gratuit dans les collèges . Méningocoque B et coqueluche : selon le calendrier vaccinal . Vérifie ton carnet / l''application VaccinServices de l''Assurance Maladie', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '1dedfd2a992cb27da348ff8e807e36ab') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Premiers secours (PSC1)', 'Soin . Vérifie l''alerte et appelle les secours (15 ou 112) avant de toucher . Parle à la victime, surveille sa respiration . Malaise : allonge et surélève les jambes · Chaleur : au frais, hydrate . Brûlure : refroidir 15 min à l''eau claire, ne rien mettre dessus . Le PSC1 (14 h) est ouvert à tous dès 12 ans — utile à mettre sur un CV santé', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'a0d5ca1b1132a354ef1187ff71f6a0cf') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Ordonnance et mutuelle', 'Soin . L''ordonnance est établie par un médecin ou un dentiste . La Sécurité sociale rembourse selon le tarif (prix du laboratoire) . La mutuelle complète le reste à charge, surtout en dentaire et lunettes . Conserve 5 ans tes ordonnances et factures', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'de416d38d2f07e7d0f9befa98c0bc4ca') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Glossaire santé', 'Soin . Consultation : le rendez-vous avec un médecin . Hospitalisation : séjour à l''hôpital avec chambres et services . Réanimation : service des patients les plus graves . DOS et DPAD : système de santé numérique . Pathologie : le nom médical d''une maladie', 'med', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '0aea508d30b5ee354e7a4f9a5868b4db') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Architecte', 'Bac général (spé maths, physique ou STI2D) puis école d''architecture (5 à 6 ans après le bac) ou licence + master archi . salaire 2 000 à 3 200 € brut/mois (junior), 3 500 à 5 000 € (confirmé) . debouches Agences, bureaux d''études, collectivités, maîtrise d''ouvrage, indépendant . comment devenir Architecte . taches etudies pour Architecte', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'b673929d709600b60b761cd5143ba270') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Avocat', 'Licence de droit (3 ans) + master en droit (2 ans), puis école d''avocats (3 ans) et serment devant la cour d''appel . salaire 2 000 à 4 000 € brut/mois à l''entrée, beaucoup plus en cabinet d''affaires . debouches Cabinet indépendant, association, entreprise, barreau, avocat d''entreprise . comment devenir Avocat . taches etudies pour Avocat', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '513045651ca820abdba5a7dcca02e7bc') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Notaire', 'Bac général puis école notariale après licence/master en droit ou BTS notariat (5 à 7 ans après le bac) . salaire 2 500 à 4 500 € brut/mois, plus en étude que fait partie . debouches Étude notariale, successe, notaire associé, officier public . comment devenir Notaire . taches etudies pour Notaire', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'b77eca509debda72488a099974847d27') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Juge', 'Licence + master en droit, puis concours de l''École nationale de la magistrature (31 mois de formation) . salaire 2 300 à 4 000 € brut/mois selon le grade . debouches Tribunal, cour d''appel, parquet, juridictions administratives . comment devenir Juge . taches etudies pour Juge', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '502c753d2d0ed52cdf5ed5eab66140fd') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Greffier', 'Master en droit ou BTS notariat, puis concours de greffier et formation à l''ENM . salaire 1 800 à 3 000 € brut/mois . debouches Greffe des tribunaux et cours d''appel, greffier des entreprises . comment devenir Greffier . taches etudies pour Greffier', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '4094659f38591bb209e1a8312cbd0d62') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Huissier de justice', 'Bac+2 ou Bac+3 (droit, BTS notariat) puis école des huissiers (3 ans) et stage . salaire 1 800 à 3 500 € brut/mois . debouches Étude de commissaire de justice, recouvrement, constats . comment devenir Huissier de justice . taches etudies pour Huissier de justice', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '92348dfc6b062a02a0a3dbd9c8bce922') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Journaliste', 'École de journalisme (ESJ Lille, IEP, 3 à 5 ans) ou licence + master information-communication, avec stages . salaire 1 600 à 2 800 € brut/mois . debouches Presse écrite, TV, radio, pure player, agence, communication . comment devenir Journaliste . taches etudies pour Journaliste', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'f559f4e96c79c77fc571eb78ffbcaf6d') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Enseignant', 'Master MEEF ou concours (CRPE, CAPES) après licence ; professeur des écoles : école supérieure du professorat (5 ans) . salaire 1 800 à 3 200 € brut/mois . debouches École maternelle et élémentaire, collège, lycée, privé sous contrat . comment devenir Enseignant . taches etudies pour Enseignant', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'c5285792fe963fb88e071dd9a401772b') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Psychologue', 'Licence de psychologie (3 ans) + master (2 ans, 500 heures de stage) . salaire 1 700 à 2 600 € brut/mois . debouches Hôpital, cabinet libéral, entreprises, écoles, justice, sport . comment devenir Psychologue . taches etudies pour Psychologue', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'b57c7e0cd9e9c4d99c792fc19de0601a') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Pilote de ligne', 'Bac+2/3 puis école de pilotage (12 à 18 mois, 80 000 à 100 000 €) ou école d''ingénieurs + licences PPL, CPL, ATPL . salaire 2 500 à 6 000 € brut/mois . debouches Compagnies aériennes, aviation d''affaires, cargo, instructeur . comment devenir Pilote de ligne . taches etudies pour Pilote de ligne', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'a90d8b4fbbbe2a6996e409521b0aebed') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Hotesse ou steward de l''air', 'Bac+2/3 (BTS tourisme, école d''hôtellerie) puis recrutement et formation par la compagnie . salaire 1 600 à 2 500 € brut/mois + primes . debouches Compagnies aériennes, aviation d''affaires . comment devenir Hotesse ou steward de l''air . taches etudies pour Hotesse ou steward de l''air', 'autre', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'a1fc81f30703a5246fb5cc525deebb0e') ON CONFLICT (content_hash) DO NOTHING;
