INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Comment choisir son orientation ?', 'Fais trois listes : ce que tu aimes faire, ce que tu sais faire, ce qui recrute. Puis élimine — le bon choix se fait par élimination, pas par révélation. Lance ensuite le test d''orientation (12 questions) : il te donne un pourcentage par secteur, puis explore les fiches secteurs et la section « Tous les métiers ».', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '75003bfa3d6f7958789f5ea157cf24d4') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Parcoursup, comment ça marche ?', 'Parcoursup est la plateforme française pour postuler après la 3e (filières au lycée) et après le bac (licences, BTS, BUT, écoles). Candidatures de janvier à mars, réponses d''avril à juin, phase de complément l''été. Tu peux formuler 20 vœux : ils ne sont pas classés, donc postule large.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '3a743f00c920ab2163521828cedcefe1') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Quelle différence entre licence, BUT et BTS ?', 'BTS et BUT durent 2 ans (bac+2), sélectifs et très professionnalisants. La licence dure 3 ans (bac+3), non sélective (sauf PASS/LAS pour la santé), plus théorique. Les trois sont reconnus par l''État et ouvrent vers un master ou l''emploi.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'e12d6ca5f8493127b558710c2abb6e36') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Comment financer ses études ?', 'Bourse sur critères sociaux (CROUS), alternance (l''entreprise paie la formation et te verse un salaire), job étudiant, prêt étudiant, APL/CAF. À l''étranger : DAAD (Allemagne), Chevening et bourses universitaires (Royaume-Uni), bourses du Canada, aides des universités américaines.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'b43ea4136686e7989491e76de2429f11') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Que faire après le bac général ?', 'Licence à l''université (3 ans), BTS ou BUT (2 ans), classe préparatoire puis grande école (5 ans), écoles spécialisées (commerce, ingénieur, santé), ou une année de césure. Aucune voie n''est « meilleure » : choisis selon ton rythme, ton budget et ton projet.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '8e82acf0a4941604f81e5bbe19de248a') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Qu''est-ce que l''alternance ?', 'L''alternance mêle cours et travail en entreprise (apprentissage ou contrat de professionnalisation). L''entreprise finance une partie de ta formation, tu touches un salaire (jusqu''à 100 % du SMIC selon l''âge) et tu sors avec de l''expérience. Disponible en BTS, BUT, licence pro et école.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '62a31a0cef555def4efa8bbf6c0d9cda') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Peut-on étudier à l''étranger sans être bilingue ?', 'Oui. Au Canada francophone (Québec, Université de Montréal, Laval, uOttawa) tout est en français. En Allemagne, de nombreux masters sont en anglais. Au Royaume-Uni et aux États-Unis, il faut un IELTS/TOEFL (souvent 6,0-7,0 ou 80-100). Le DELF/DALF est aussi accepté certaines écoles.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '6556590f1344df06e24104a746ef2ca2') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Quels documents pour candidater à l''étranger ?', 'Relevés de notes, diplôme ou attestation, lettre de motivation, CV, test de langue (IELTS/TOEFL/TEF/TestDaF), lettres de recommandation, parfois un portfolio. Le Royaume-Uni passe par UCAS, l''Allemagne par uni-assist, les États-Unis demandent souvent le SAT, le Canada un dossier provincial.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'e287357528fb28804ab4faaf505a0f6f') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Combien coûte la vie étudiante ?', 'France : 800-1 200 €/mois. Canada : 1 200-2 000 $CA/mois. Royaume-Uni : 1 000-1 400 £/mois. États-Unis : 1 000-1 800 $/mois. Allemagne : 850-1 100 €/mois (logement moins cher hors Munich et Hambourg). Pense aux résidences universitaires et aux colocations.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '9ffdee71ebb2af6aefa3ff4bcde2f134') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Je n''ai aucune idée de ce que je veux faire ?', 'C''est le cas de la majorité des élèves. Élimine d''abord les secteurs qui ne t''intéressent pas du tout, puis regarde les 3-4 restants. Fais le test, ouvre trois fiches secteurs et note ce qui te donne envie. Tu n''as pas besoin d''une évidence : tu as besoin d''un premier choix révisable.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'bea3ae6b7cc62bcdc24f8d0576c765dd') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Comment se passe le test d''orientation ?', '12 questions, 3 réponses chacune, environ 3 minutes. À la fin : un pourcentage par secteur, les établissements conseillés dans la région de ton choix, et la possibilité de recevoir le tout par e-mail. Tu peux le refaire autant de fois que tu veux.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '14dfe81027bb089fd7db4394e3269bfa') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('C''est quoi l''alternance entre un métier et une formation ?', 'Chaque métier indique les études qui y mènent (CAP, Bac Pro, BTS, BUT, licence, école, concours) et le salaire associé. Utilise la section « Tous les métiers » avec les filtres par secteur, puis ouvre la fiche complète du secteur pour voir toutes les formations.', 'faq', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'c51b7a649e8638f5e1e0cf457211fb7d') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de la médecine', 'La médecine est l''un des plus anciens savoirs organisés : née comme discipline morale dans la Grèce antique, elle s''est professionnalisée avec les universités médiévales, puis a basculé vers la science expérimentale au XIXe siècle avant de devenir technologique, chirurgicale et génomique. . Dans la Grèce antique, Hippocrate sépare la maladie de la punition divine : la médecine devient un art d''observer et de raisonner. Galien, médecin des gladiateurs puis des empereurs à Rome, impose pendant plus de mille ans la théorie des humeurs — qui ne sera réellement démolie qu''à la Renaissance. . Au Moyen Âge, les facultés de Montpellier puis de Paris structurent l''enseignement et délivrent des maîtrises ; les hôpitaux, comme l''Hôtel-Dieu de Paris, deviennent à la fois lieux de soin et lieux d''apprentissage. L''Anatomie reprend le dessus avec Vésale, qui dissèque et corrige Galien plutôt que de le réciter, puis Harvey qui décrit la circulation sanguine. . Le XIXe siècle est le grand basculement : Jenner (vaccin, 1796), l''anesthésie (éther, 1846), l''asepsie (Lister, 1867), la théorie des germes et les vaccins de Pasteur, les rayons X (1895), les groupes sanguins (1901). Le XXe ajoute les antibiotiques (pénicilline, 1928, utilisée massivement dès 1943), l''imagerie, les greffes (première greffe de cœur, 1967), la fécondation in vitro (1978) et le séquençage du génome humain (2003). Aujourd''hui, la médecine est de plus en plus préventive, numérique et individualisée. . ≈ 460 – 370 av. J.-C. — Hippocrate : la médecine comme observation, non comme miracle . IIe siècle — Galien domine la pensée médicale occidentale jusqu''au XVIe siècle . 1220 et suivantes — facultés de médecine de Montpellier puis de Paris . 1543 — André Vésale, De humani corporis fabrica : l''anatomie par la dissection . 1628 — William Harvey décrit la circulation du sang . 1796 — Edward Jenner : premier vaccin (variole) . 1846 — première anesthésie publique à l''éther (Massachusetts General Hospital) . 1861-1885 — Pasteur : théorie des germes, vaccins anticholérique et antirabique . 1895 — Wilhelm Röntgen découvre les rayons X . 1901 — Karl Landsteiner découvre les groupes sanguins . 1928 — Alexander Fleming isole la pénicilline (usage de masse dès 1943) . 1953 — Watson, Crick et Rosalind Franklin : la structure de l''ADN . 1967 — Christiaan Barnard réalise la première greffe de cœur . 2003 — fin du séquençage du génome humain . 2020 — vaccination à ARN messager en quelques mois', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '301b29f67b5af4f0aca6b9d90378c18a') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire des soins infirmiers', 'Pendant des siècles, soigner est un travail de religieuses, de sages-femmes et de familles : c''est au XIXe siècle que les soins infirmiers deviennent un métier organisé, diplômé, puis public — jusqu''à l''autonomie d''exercice actuelle. . Avant le XIXe siècle, le soin aux malades appartient aux ordres religieux et aux communautés charitables ; les « gardes-malades » apprennent sur le tas, sans statut. Les guerres révolutionnaires puis napoléoniennes révèlent l''ampleur du problème : les blessés meurent autant de leurs plaies que du combat. . Tout change avec la guerre de Crimée : Florence Nightingale, à Scutari (1854-1856), organise l''hygiène, l''ordre et le suivi des blessés — la mortalité chute spectaculairement. De retour à Londres, elle ouvre en 1860 la première école d''infirmières à l''hôpital St Thomas'', qui servira de modèle au monde entier. En France, Sœur Marthe fonde en 1868 à Pau les Petites Sœurs de l''Assistance, congrégation vouée au soin des malades pauvres. . Le XXe siècle fait entrer le métier dans la sphère publique : l''École du service de santé militaire, puis les écoles nationales d''infirmières ; en 1992, les IFSI (instituts de formation en soins infirmiers) remplacent les écoles et allongent le cursus. Depuis les années 2000, les infirmiers peuvent prescrire pour certains actes ; en 2020, ils prennent une part décisive dans la campagne de vaccination. Le métier est aujourd''hui celui de la santé le plus exercé — et le plus en tension. . Moyen Âge – XVIIIe siècle — soins confiés aux communautés religieuses et aux familles . 1854-1856 — Florence Nightingale à Scutari (guerre de Crimée) . 1860 — première école d''infirmières de Nightingale (Londres) . 1868 — Sœur Marthe fonde les Petites Sœurs de l''Assistance (Pau) . 1920-1940 — écoles nationales d''infirmières de santé publique en France . 1992 — création des IFSI (3 ans après le bac) . 2004 — infirmiers habilités à prescrire certains actes et médicaments . 2020 — rôle central des infirmiers dans la vaccination COVID-19', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'ad3257c048af159da6e35834395d3f06') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de la pharmacie', 'La pharmacie descend des herbes et des potions antiques : elle est devenue, en deux millénaires, une science des molécules, réglementée de très près, au point d''être aujourd''hui le maillon qui relie le diagnostic à la thérapeutique. . Dioscoride, au Ier siècle, décrit dans sa Materia medica quelque 600 plantes : c''est la pharmacopée de référence pendant plus de quinze siècles. Au Moyen Âge, les apothicaires — corporés, surveillés, souvent mêlés aux épiciers — préparent les préparations que les médecins prescrivent ; l''officine devient un lieu de savoir autant que de commerce. . La chimie change la donne : Paracelse (1493-1541) impose l''idée qu''on peut doser un remède plutôt qu''empirer, et la pharmacie moderne naît au XIXe siècle avec les alcaloïdes isolés (morphine, quinine, strychnine). En 1897, Felix Hoffmann synthétise l''acide acétylsalicylique — l''aspirine — et la pharmacie industrielle est née. La pénicilline (1928), industrialisée pendant la Seconde Guerre mondiale, montre que les médicaments peuvent sauver des populations entières. . Aujourd''hui, le pharmacien est le professionnel de santé le plus accessible : il conseille, délivre, vaccine et suit chroniques. La France compte l''un des réseaux d''officines les plus denses d''Europe, et le médicament reste soumis à une chaîne complète : recherche, essais cliniques, autorisation, prix, pharmacovigilance. . Ier siècle — Dioscoride : la Materia medica, base de la pharmacopée . XIIIe-XVe siècle — corporations d''apothicaires, distinction avec les épiciers . 1541 ? — Paracelse : doses et remèdes chimiques . 1804 — opium : première isolation de la morphine . 1897 — aspirine (acide acétylsalicylique) . 1928-1943 — pénicilline : du laboratoire à la production de masse . 1965 en France — contrôle de l''innovation thérapeutique (loi caractéristiques essentielles du médicament) . 2020 — premiers vaccins à ARN messager autorisés en quelques semaines', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '271f6ba48eb73cede5864fe937223451') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de l''informatique', 'L''informatique est une discipline jeune : née de la logique, de l''électronique et des besoins de guerre, elle est passée en soixante-dix ans des salles climatisées aux poches de tous, avant de produire l''intelligence artificielle générative. . Les fondations sont intellectuelles avant d''être techniques : Leibniz rêve d''un calcul universel, Boole formalise le raisonnement en 1847, et Ada Lovelace écrit au milieu du XIXe siècle ce que l''on considère comme le premier algorithme, pour la machine analytique de Charles Babbage — un ordinateur qui ne sera jamais construit. En 1936, Alan Turing définit ce qu''est un calculateur universel : toute machine capable de lire une description de tâche pourra l''exécuter. . L''informatique naît physiquement pendant la Seconde Guerre mondiale et juste après : les machines à calculer de Bletchley Park, puis ENIAC (1945), occupent des pièces entières. Le transistor (1947), le circuit intégré (1958) et le microprocesseur (Intel 4004, 1971) réduisent tout : l''ordinateur quitte la salle, puis le bureau, puis la poche. En parallèle, les langages émergent (Fortran, COBOL, puis C en 1972, Python en 1991) et le logiciel devient un métier à part entière. . Les réseaux font le reste : ARPANET (1969), puis Internet (protocole TCP/IP en 1983), le World Wide Web inventé par Tim Berners-Lee au CERN (1989, ouvert à tous en 1991), les moteurs de recherche, les réseaux sociaux, le cloud, le mobile. Depuis 2012, l''apprentissage profond ouvre l''ère de l''IA ; en 2022, les modèles génératifs rendent l''intelligence artificielle conversationnelle — c''est exactement ce que vous avez sous les yeux. . 1837-1843 — machine analytique de Babbage et algorithmes d''Ada Lovelace . 1936 — Alan Turing formalise la machine universelle . 1945 — ENIAC, premier ordinateur électronique programmable . 1947-1958 — transistor puis circuit intégré : la miniaturisation . 1971 — microprocesseur Intel 4004 . 1972 / 1991 — langages C puis Python . 1969-1983 — ARPANET puis TCP/IP : Internet . 1989-1991 — World Wide Web (Tim Berners-Lee, CERN) . 1998 — Google . 2007 — l''iPhone et l''informatique mobile . 2012 — révolution de l''apprentissage profond (deep learning) . 2022 — IA générative conversationnelle', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'b6d1aab2a4e6b6c6e58eb886fe2fb097') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire d''Internet et des télécommunications', 'Histoire d''une idée simple — relier des machines — devenue en un siècle la colonne vertébrale de l''économie, de la culture et de la conversation mondiale. . Tout commence par transmettre plus vite que le cheval : le télégraphe électrique de Cooke et Wheatstone (1837) puis celui de Morse relient déjà les villes ; le téléphone de Bell (1876) fait entrer la voix dans le circuit, et la radio de Marconi (1895-1901) supprime enfin le fil. Chaque invention redéfinit les métiers : télégraphistes, opérateurs, ingénieurs radio, techniciens des réseaux. . Internet naît d''une logique de résilience : l''agence américaine DARPA imagine dans les années 1960 un réseau qui survivrait à la destruction d''un nœud. ARPANET connecte quatre universités en 1969, le protocole TCP/IP devient standard en 1983, et le domaine .fr est créé en 1987. En 1989, Tim Berners-Lee propose au CERN un système de documents reliés entre eux — le Web — qui est rendu public en 1991. . La démocratisation suit : Netscape (1994), la messagerie, les blogs, Wikipédia (2001), Facebook (2004), YouTube (2005), l''iPhone (2007), le haut débit mobile (4G, puis 5G). En vingt ans, le réseau devient plateforme : commerce, presse, musique, éducation, santé. Les métiers qui en vivent — développeur, community manager, data analyst, référencement, cybersécurité — n''existaient pas il y a trente ans. . 1837 — télégraphe électrique (Cooke et Wheatstone) . 1876 — téléphone (Alexander Graham Bell) . 1895-1901 — télégraphie sans fil (Guglielmo Marconi) . 1969 — ARPANET : premier échange entre 4 universités . 1983 — TCP/IP : le protocole d''Internet . 1987 — création du domaine .fr . 1989-1991 — World Wide Web, puis mise à disposition de tous . 1994-2001 — navigateurs, moteurs de recherche, Wikipédia . 2004-2007 — réseaux sociaux et téléphone intelligent . 2013-2020 — 4G puis 5G, haut départ partout', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '2e9788f681ace88ccba6e4b7bc23a6a9') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de l''architecture', 'De l''abri à la ville, l''architecture est le métier qui donne une forme à la société : elle raconte ses religions, ses pouvoirs, ses techniques et ses peurs — et elle doit toujours tenir debout. . Les premiers monuments servent d''abord les dieux et les morts : temples grecs construits selon des proportions canoniques, pyramides égyptiennes, aqueducs romains qui sont déjà du génie civil. La Rome antique invente la voûte, le béton antique et l''urbanisme d''empire ; avec la chute de Rome, ce sont les moines et les cathédrales qui gardent le savoir. . La Renaissance redécouvre Vitruve et codifie l''ordre classique ; Brunelleschine ouvre en 1420 le dôme de Florence, exploit technique de son siècle. Puis viennent le baroque, le néoclassicisme, et surtout le XIXe siècle des volumes de fer, de verre et d''acier : la halle du Grand Palais, les gares, les gratte-ciel américains. En France, l''Ordre des architectes est créé en 1977 : l''exercice devient un métier réglementé. . Le XXe siècle casse les règles : le béton armé permet les formes libres (Le Corbusier, Bauhaus), puis le modernisme, les tours de banlieue, et la réaction postmoderne. Aujourd''hui l''architecture est surtout un défi d''environnement : rénovation thermique, matériaux bas carbone, densification des villes, conception assistée par ordinateur (BIM) et participation des habitants. . ≈ 3000 av. J.-C. — pyramides et techniques de construction égyptiennes . VIIIe-VIe siècle av. J.-C. — ordres grecs et proportions canonniques . IIe siècle — Panthéon de Rome : la voûte et le béton antique . 1420-1436 — dôme de Brunelleschine, Florence . 1671 — Académie royale d''architecture (France) . 1747 — École des ponts et chaussées : la formation des ingénieurs . 1919 — Bauhaus : forme, fonction, industrie . 1977 — création de l''Ordre des architectes en France . 1990-2010 — conception numérique (CAO, puis BIM) . 2020 — priorité à la rénovation et au bas carbone', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '6e59fbb4b11c6910096afc84a0ad2450') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire du bâtiment et du génie civil', 'Le bâtiment et les travaux publics sont les métiers les plus vieux du monde — couper une pierre, dresser un pont, drainer un champ — révolutionnés en deux siècles par l''acier, le béton armé et la machine. . Les grandes constructions antiques sont déjà du génie civil : les aqueducs romains tombent d''une pente minimale sur des dizaines de kilomètres, les ponts médiévaux tiennent encore, les cathédrales sont des exploits de calcul sans ordinateur. Le savoir reste oral, transmis de compagnon à apprenti : les compagnonnages structurent le métier du bâtiment du Moyen Âge à nos jours. . La période moderne institutionalise la formation : Trudaine fonde en 1747 l''École des ponts et chaussées, qui forme les ingénieurs des routes, canaux et ouvrages d''art ; les canaux de Bourgogne, du Midi puis les grands viaducs du XIXe siècle en sont la démonstration. Le fer puis l''acier, et surtout le béton armé breveté par Hennebique à la fin du XIXe siècle, changent la portée de tout : on peut désormais franchir plus large et bâtir plus haut. . Le XXe siècle industrialise la construction : préfabrication, grues, métro de Paris (1900), tours, barrages, autoroutes ; et surtout l''après-guerre qui remet les pays à bâtir. Depuis les années 2000, le chantier se transforme : simulation numérique (BIM), maisons bois, rénovation énergétique des logements anciens — le plus gros gisement d''emplois du XXIe siècle en France — et robotisation sur site. . Antiquité — aqueducs, thermes, routes romaines . Moyen Âge — cathédrales et ponts calculés à la main . 1747 — création de l''École des ponts et chaussées . 1789-1869 — grands canaux et chemins de fer . 1860-1900 — ponts en acier et tours métalliques . 1890-1910 — béton armé (Hennebique) : toutes les formes possibles . 1900 — métro de Paris . 1945-1975 — logements et infrastructures à l''échelle d''un pays . 2000 — conception numérique collaborative (BIM) . 2018-2030 — rénovation énergétique de millions de logements', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'e389d48190a2165658bcef1856a8bb6a') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de l''industrie et de la mécanique', 'L''industrie est née d''une idée : fabriquer en série, vite et au même prix. Elle a redessiné les villes, les salaires, les horaires — puis, en s''automatisant, a transformé le geste ouvrier en métier de technique et de maintenance. . Avant la machine, il y a l''atelier : forge, moulin, tisserand, marteau piloté par l''eau. La révolution industrielle commence en Angleterre quand James Watt perfectionne la machine à vapeur (brevet de 1769) et que le cokéfage permet de faire fondre le fer en masse. La manufacture remplace l''artisan : la productivité explose, la main-d''œuvre se regroupe, les villes doublent. . Au XIXe siècle, la France industrialise ses bassins — Le Creusot, Lille, Saint-Étienne, Lyon soie — et invente ses grandes écoles : Arts et Métiers (1780), Centrales (1829). L''Amérique pousse plus loin : en 1913, Henry Ford installe la chaîne de montage : un châssis passe en 93 secondes, la voiture devient abordable. Le XXe siècle apporte l''automation, puis le robot : Unimate, premier robot industriel, travaille en 1961. . Depuis, l''usine est devenue propre, connectée et pilotée : méthodes de qualité (Toyota, Kaizen), gestion de la chaîne d''approvisionnement, jumeaux numériques, et « industrie 4.0 » — capteurs, données, maintenance prédictive. Le métier a changé de niveau : moins de force, plus d''électronique, de programmation et de diagnostic, avec une pénurie durable d''opérateurs qualifiés. . 1769 — brevet de la machine à vapeur améliorée (James Watt) . 1780-1829 — Arts et Métiers puis École centrale . 1810 — invention de la conserve (Nicolas Appert) . 1856 — procédé Bessemer : acier à bas coût . 1913 — chaîne de montage chez Ford . 1961 — premier robot industriel (Unimate) . 1970-1990 — robotisation et informatique de production . 1990-2010 — systèmes de qualité et production allégée . 2010-2020 — industrie 4.0, capteurs, données, maintenance prédictive', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '45e87313c52ca53b50da81b0236cbbb5') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de l''électricité et de l''énergie', 'L''électricité est le seul flux qui soit apparu industriellement en moins d''un siècle : de la première pile à la fusion des réseaux, elle a créé des métiers entiers — et le débat qui structure notre siècle, celui de produire sans réchauffer. . Tout part de la pile de Volta (1800), première source d''électricité stable, puis des travaux d''Faraday sur l''induction (1831) qui permettent de la produire en tournant une machine. Edison et Westinghouse s''affrontent à la fin du XIXe siècle entre courant continu et alternatif ; le courant alternatif l''emporte et la centrale électrique de Pearl Street (1882) alimente ses premiers clients. La lampe à incandescence et le moteur électrique transforment l''usine, l''éclairage et le transport urbain. . Le XXe siècle ajoute la transmission (les lignes à haute tension parcourent des milliers de kilomètres) et la production de masse : hydraulique, charbon, pétrole, puis nucléaire — première centrale nucléaire civile en 1956-1958 en URSS, programme français lancé en 1974, Fessenheim raccordée en 1977. Le nucléaire couvre aujourd''hui environ les deux tiers de l''électricité française, complété par l''hydraulique, l''éolien, le solaire et le gaz. . La question n''est plus seulement de produire, mais de produire proprement : effacement des consommations, stockage, réseaux intelligents, rénovation des bâtiments, hydrogène. Les métiers qui en découlent — ingénieur énergéticien, technicien de maintenance éolienne, installateur photovoltaïque, chef de projet réseaux — sont parmi les plus recrutés de la décennie. . 1800 — pile de Volta . 1831 — induction électromagnétique (Michael Faraday) . 1879 — lampe à incandescence utilisable (Edison) . 1882 — première centrale électrique commerciale (Pearl Street, New York) . 1900 — métro et tramway électriques à Paris . 1956-1958 — première centrale nucléaire civile (Obninsk, URSS) . 1977 — raccordement de Fessenheim, première centrale nucléaire française . 1990-2010 — éolien et solaire deviennent compétitifs . 2020 — lois climat : rénovation, réseaux et sobriété au menu', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'dc8d05b98e23af9c189f7f66f1251649') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de l''agriculture', 'L''agriculture est le métier qui a rendu les sociétés sédentaires : elle est passée de la houe aux satellites, en passant par la charrue, l''engrais et la mécanisation — sans jamais cesser d''être le maillon de départ de toute la chaîne alimentaire. . Vers 10 000 ans avant notre ère, dans le Fertile Crescent puis en Inde, en Chine et en Amérique, les premiers humains sédentaires sélectionnent les plantes sauvages : blé, orge, riz, maïs. L''agriculture invente le grenier, la propriété, la ville — et avec elle les métiers de l''agronomie, de l''irrigation et du élevage. La charrue, attestée dans l''Antiquité, puis les assoches successives structurent les campagnes européennes pendant deux millénaires. . Le XVIIIe-XIXe siècle mécanise et chimise : semoir de Tull (1701), charrue de Rotherham, sélection des races, puis les engrais de synthèse (procédé Haber-Bosch, 1909-1913) qui doublent quasiment les rendements au XXe siècle. La « révolution verte » des années 1950-1970, portée par Norman Borlaug, sauve des centaines de millions de personnes de la famine en multipliant les variétés à haut rendement — au prix d''usages intensifs qu''on questionne aujourd''hui. . Depuis les années 2000, l''agriculture se réinvente : agriculture biologique (label européen en 2009), agriculture de précision (guidage GPS, drones, capteurs), réduction des pesticides, circuits courts, agriculture urbaine, et surtout une part croissante de travail de bureau — données, conseil, certification, énergie. L''alimentaire agroalimentaire transforme au plus près : la France est une puissance de cette filière. . ≈ 10 000 av. J.-C. — domestication des plantes (Fertile Crescent) . Antiquité — charrue, arrosage, tri des récoltes . 1701 — semoir de Jethro Tull . 1789-1815 — grandes explorations botaniques et sélection . 1909-1913 — engrais azotés de synthèse (Haber-Bosch) . 1940-1960 — mécanisation complète des campagnes . 1950-1970 — révolution verte (Norman Borlaug) . 1962 — politique agricole commune (PAC) . 2009 — label européen « bio » . 2010-2025 — agriculture de précision, drones, capteurs, réduction des intrants', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '79d339b2a045ad329eb469601e11bc75') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de la cuisine et de la restauration', 'Cuisiner est probablement le plus ancien des gestes professionnels : il est passé du feu de clan aux brigades de restaurants, en passant par les guildes médiévales et l''invention du restaurant moderne. . Pendant des millénaires, la cuisine est domestique ou communautaire ; elle se professionnalise avec les pouvoirs : cuisiniers de pharaons, de Rome, puis des cours médiévales où les offices (cuisinier, écuyer, panetier) forment une hiérarchie stricte. Dans les villes, les guildes et les maîtres cuisiniers réglementent l''exercice : qui a le droit de vendre quoi, et à quel prix. . La restauration comme commerce naît à Paris : les « restaurants » du XVIIIe siècle servent des bouillons réconfortants, puis la Révolution met à la disposition des cuisiniers des grandes maisons une main-d''œuvre et une clientèle nouvelles. Marie-Antoine Carême (1784-1833) codifie la grande cuisine française et la dote d''un répertoire de techniques ; Auguste Escoffier, avec Le Guide culinaire (1903), organise la brigade de cuisine dont on hérite encore : chefs, chefs de rang, pâtissiers, commis. . Le XXe siècle divise et élargit : la « nouvelle cuisine » des années 1960-1970 (Bocuse, Troisgros, Guérard) allège, valorise le produit et le dressage ; le fast-food arrive et fait exploser la restauration rapide ; puis viennent les cuisines du monde, le bio, le local, la food-truck et l''éco-responsabilité. Les écoles professionnelles (baccalauréat professionnel, CAP, instituts de formation) forment un secteur qui recrute en continu, saison après saison. . Antiquité — cuisiniers de cour et guildes de métiers . Moyen Âge — offices de bouche, règlements des villes . 1765 — ouverture des premiers « restaurants » à Paris . 1784-1833 — Marie-Antoine Carême : codification de la grande cuisine . 1903 — Auguste Escoffier, Le Guide culinaire et la brigade . 1935 — création des Guide Michelin et des étoiles . 1960-1970 — la nouvelle cuisine . 1970-1990 — essor de la restauration rapide . 2000-2020 — circuits courts, bio, cuisine durable', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'bb0e4bb905a2c1a3ba8b756e8e1d9426') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire des transports et du ferroviaire', 'Le transport est le métier qui rapproche les distances : cheval, bateau, locomotive, avion — chaque saut technologique a rétréci le monde et créé une nouvelle profession. . Le transport reste pendant des millénaires un affaire de muscle et de vent : bœufs, chevaux, voiles, chemins de pierre. Les romains, les Arabes, les Han et les Incas construisent des routes pour l''armée et le commerce ; les villes vivent à distance de marche. Rien ne change vraiment avant la vapeur. . La vapeur supprime l''effort : la locomotive de Trevithick (1804) ouvre la voie, la ligne Stockton-Darlington (1825) puis Liverpool-Manchester (1830) prouvent que le chemin de fer marche ; la France s''y met dès 1832 et bâtit un réseau dense tout au long du siècle. Le rail crée des métiers entiers — mécaniciens, chefs de gare, aiguilleurs, wagonniers — et impose l''heure commune, les horaires, la ponctualité. Le XXe siècle ajoute la route (camions, autoroutes), le métro et l''avion de ligne. . Aujourd''hui le transport est une chaîne logistique pilotée par la donnée : trafic ferroviaire convoié, transport routier de marchandises et de voyageurs, transport maritime, gestion des flux, douanes, service client. Les licences et autorisations professionnelles réglementent l''accès au métier, et la transition énergétique (poids lourds électriques, autoroutes ferroviaires, Navettes) réinvente chaque segment. . Antiquité — routes romaines, relais, ports antiques . 1804 — première locomotive à vapeur (Richard Trevithick) . 1825 — ligne de Stockton à Darlington . 1830 — Liverpool-Manchester : le rail passe à l''échelle . 1832 — premières lignes en France (Paris-Orléans à cheval puis vapeur) . 1860-1914 — grands réseaux, gares et paquebots . 1938 — création de la SNCF . 1950-1970 — essor de l''automobile et des autoroutes . 1981 — TGV Paris-Lyon . 1994 — tunnel sous la Manche', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '05d9ba5e1ea2f8bf97039196bf7a1bd2') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de l''aviation', 'Il a fallu des siècles d''observations et treize années de tâtonnements pour voler : du planeur au drone, l''aviation est le métier où la sécurité s''est construite sur chaque accident. . Le rêve est ancien — Icare, les planeurs de Cayley au début du XIXe siècle, Otto Lilienthal qui vole réellement en 1890s — mais l''exploit revient aux frères Wright : le 17 décembre 1903, à Kitty Hawk, un appareil de 260 kilos reste douze secondes dans l''air. Puis tout va très vite : Louis Blériot traverse la Manche en 1909, la Première Guerre mondiale fait de l''avion une arme et de la mécanique une industrie. . L''entre-deux-guerres et la Seconde Guerre mondiale professionnent l''aéronautique : lignes postales, radars, réacteurs (le Gloster E.28/39 vole en 1941), fusées. Après 1945, l''aviation civile explose : le Douglas DC-3, la Caravelle (1959) qui invente les réacteurs arrière, le Boeing 747 (1969) qui démocratise le voyage lointain, Concorde (premier vol en 1969, mise en service en 1976) qui rapproche l''Atlantique en trois heures et demie. . Depuis les années 2000, le secteur s''attaque à l''équilibre entre vitesse, coût et climat : avions plus sobres, gestion de trafic à la demande, avions électriques et hybrides en essai, drones civils en plein essor, et des métiers en tension — pilotes, ingénieurs aéronautiques, techniciens de maintenance, contrôle aérien, gestion aéroportuaire. . 1783 — premiers ballons montgolfière et charlière . 1890-1900 — planeurs d''Otto Lilienthal . 17 décembre 1903 — les frères Wright : le premier vol motorisé . 1909 — Blériot traverse la Manche . 1914-1918 — l''avion devient une industrie de guerre . 1935 — Douglas DC-3 : le transport aérien rentable . 1941 — premiers vols à réaction . 1959 — la Caravelle, avion à réacteurs français . 1969 — Concorde (premier vol) et Boeing 747 . 2010-2025 — drones civils, avions sobres, électrification', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '01112218bc5cbe661ab928958082865c') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire du droit et des avocats', 'Le droit est l''instrument avec lequel une société écrit ses règles : de la loi du plus fort au texte publié et discuté, l''avocat et le juge sont les métiers de cette longue mise en ordre. . Les codes les plus anciens servent surtout à montrer la puissance du prince : code de Hammurabi (XVIIIe siècle av. J.-C.), lois de Moïse, droit romain qui, lui, structure la pensée juridique occidentale pour des siècles — procédure, propriété, contrat, personnes. L''avocat romain (advocatus) assiste et plaide ; les sociétés médiévales réinstaurent la profession avec des confréries et des serments. . Les grandes ordonnances françaises mettent l''ordre : Villers-Cotterêts (1539) impose le français dans les actes et l''enregistrement des naissances ; la Révolution consacre la liberté de la presse et l''égalité devant la loi (Déclaration des droits de l''homme, 1789) et surtout impose un droit commun : le Code civil de 1804, napoléonien, qui reste le socle du droit privé français et a été copié dans le monde entier, suivi du Code pénal de 1810. . Le XXe siècle ajoute le droit du travail (1936, congés payés ; 1950 conventions collectives), la Sécurité sociale (1945), la Constitution de la Ve République (1958), puis la réforme du statut d''avocat (1971) et l''essor du droit européen et international (droits humains, droit de l''Union, commerce). Aujourd''hui, les métiers du droit — avocat, juriste d''entreprise, magistrat, notaire, greffier, compliance — sont stables, protégés et accessibles par des voies multiples (faculté de droit, écoles de droit, masters, concours d''accès à la magistrature). . ≈ 1750 av. J.-C. — code de Hammurabi . IIIe siècle av. J.-C. — droit romain codifié (Lois des XII Tables) . 1215 — Magna Carta (Angleterre) . 1539 — ordonnance de Villers-Cotterêts . 1789 — Déclaration des droits de l''homme et du citoyen . 1804 — Code civil français . 1810 — Code pénal . 1881 — loi sur la liberté de la presse . 1936 — congés payés et durée légale du travail . 1945-1950 — Sécurité sociale et droit du travail moderne . 1958 — Constitution de la Ve République . 1971 — réforme du statut de l''avocat . 1992 — nouveau Code pénal', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '2ff6fe506621d16d0de874acb47a258b') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de la banque, de la comptabilité et de la finance', 'La comptabilité naît d''un besoin très prosaïque : savoir ce qu''on possède et ce qu''on doit. La banque, elle, invente le crédit — donc la croissance, mais aussi les crises. . Les temples et palais antiques tiennent déjà des comptes : l''écriture sumérienne naît pour cela. La révolution conceptuelle arrive avec l''Italie médiévale : la double entrée, décrite et diffusée par Luca Pacioli en 1494 (Summa de arithmetica), permet d''équilibrer un bilan — c''est le socle de toute la comptabilité moderne. Les marchands florentins, génois et vénitiens inventent en même temps la lettre de change, l''assurance maritime et la banque d''affaires ; les Médicis pèsent déjà sur l''Europe. . Au XIXe siècle, la finance s''institutionnalise : bourse d''Amsterdam (1602) puis Paris (1724), création de la Banque de France en 1800, sociétés par actions (loi de 1867), banques de dépôt. Après les crises de 1929 et la Seconde Guerre mondiale, le système se cadrage : accords de Bretton Woods (1944), plan Marshall, création du franc fort, puis construction européenne et création de l''euro (échange à partir du 1er janvier 1999, billets en 2002). . La comptabilité devient un métier d''État en France : expert-comptable inscrit à l''Ordre, commissaire aux comptes, contrôle de gestion, audit, fiscalité — et le référentiel s''internationalise avec les normes IFRS appliquées en Europe depuis 2005. La crise de 2008 impose Bâle III et une régulation plus stricte ; fintechs, banques en ligne, paiement instantané et crypto-actifs réorientent la profession vers la donnée et la conformité. . Mésopotamie — premiers comptes sur tablette d''argile . 1494 — Luca Pacioli codifie la partie double . 1602 — création de la Compagnie néerlandaise des Indes orientales et bourse d''Amsterdam . 1800 — création de la Banque de France . 1867 — loi sur les sociétés par actions . 1929 — crise mondiale et krach de Wall Street . 1944 — accords de Bretton Woods . 1999 — création de l''euro (monnaie unique) . 2005 — adoption des normes IFRS en Europe . 2008 — crise financière, puis régulation (Bâle III) . 2010-2025 — fintechs, banques en ligne, paiement instantané', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '489b64d6a1fd65bfea6066eaaebc848d') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de l''enseignement et de l''école', 'Transmettre est un métier ancien ; l''école publique, elle, est une idée récente : gratuite, laïque et obligatoire depuis moins de cent cinquante ans en France. . Avant l''école, il y a le maître : scribes égyptiens, philosophes grecs — Platon fonde son Académie vers 387 av. J.-C. — grammairiens romains, puis les universités médiévales (Bologne, 1088 ; Paris, XIIe siècle) qui donnent le statut d''étudiant et de maître. Pendant des siècles, l''instruction reste privée, religieuse ou réservée à une élite ; l''immense majorité des gens apprend un métier, pas des lettres. . La France construit son école publique en quelques décennies : l''abbé Grégoire réclame l''instruction populaire dès 1792 ; la loi Guizot (1833) impose une école primaire dans chaque commune et une école normale par département ; Jules Ferry fait passer la gratuité (1881) puis l''obligation scolaire de 6 à 13 ans et la laïcité (1882), sans oublier la formation des instituteurs en 1881 — c''est le socle encore visible aujourd''hui. Les lycées, organisés depuis le début du XIXe siècle, forment les cadres. . Le XXe siècle étend et diversifie : classes de 6e en 1962, collèges uniques, massification des baccalauréats (la moitié d''une génération à partir des années 1980), universités ouvertes, création des IUFM (1990), puis de l''École des maîtres et des concours. Les réformes récentes (autonomie des universités en 2007, loi d''orientation 2019, parcoursup) cherchent à conjuguer exigence et réussite de tous : le métier d''enseignant reste un pilier du service public, avec un renouvellement de génération à préparer. . ≈ 387 av. J.-C. — Académie de Platon . 1088 — université de Bologne . XIIe siècle — facultés de Paris . 1792 — projet d''instruction publique populaire (abbé Grégoire) . 1833 — loi Guizot : école primaire dans chaque commune . 1881 — gratuité de l''école primaire . 1882 — obligation scolaire (6-13 ans) et école laïque (Jules Ferry) . 1959 — réforme des lycées (Clément) . 1962 — entrée en 6e au collège . 1989 — loi d''orientation sur l''éducation (création des ESP) . 2007 — autonomie des universités . 2019 — loi d''orientation et de programmation du ministère', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'ade0d0285df5309d28143810016dd7de') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de la presse et du journalisme', 'L''imprimerie a créé le journal, la presse a créé l''opinion publique, Internet a multiplié les voix — et pose au journalisme la question qu''il ne s''était jamais posée : qui peut encore certifier l''information ? . L''imprimerie de Gutenberg (années 1440) rend le texte transportable ; les gazettes du XVIe siècle (Gazetta à Venise, relation de toutes les choses) diffusent déjà des nouvelles de marché. En 1631, Théophraste Renaudot lance La Gazette à Paris, autorisée par Richelieu : c''est le premier journal français. Les pamphlets, eux, prennent le pouvoir des idées et sont régulièrement interdits. . La Révolution fait de la presse un droit : l''article 11 de la Déclaration des droits de l''homme et du citoyen (1789) proclame la liberté de communication des opinions ; la loi du 29 juillet 1881 sur la liberté de la presse, encore en vigueur, fixe le régime français (déclaration préalable, caution, diffamation). Le XIXe siècle est celui des grands journaux, puis du reportage et de la photographie ; au XXe, la radio (1920s), puis la télévision (1935 en France, puis 1954 pour le service public) bouleversent encore le métier. . Depuis 2000, la révolution est numérique : blogs, réseaux sociaux, médias en ligne, audio à la demande. L''audience explose et le modèle économique se fissure (publicité, abonnements, financement participatif, aides à la presse). Le métier se professionnalise face à la désinformation : vérification des sources, droit d''auteur, protection des sources, déontologie — et un nouveau titre, le journaliste-data ou le vidéaste, remplace progressivement le reporteur traditionnel. . ≈ 1440 — imprimerie de Gutenberg . 1631 — La Gazette de Renaudot . 1789 — article 11 : liberté de la presse . 1881 — loi française sur la liberté de la presse (encore applicable) . 1920s — premières radios . 1935 — premières émissions de télévision en France . 1944 — création de l''Agence France-Presse (AFP) . 1988 — 20 Minutes, presse gratuite . 2000-2010 — blogs, réseaux sociaux, médias en ligne . 2016-2025 — lutte contre la désinformation, fact-checking, IA générative', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, 'ef874e6a374336fb5e6c9bf86ca79bc3') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de l''art, du graphisme et du design', 'Créer est un métier aussi vieux que les grottes, mais le « designer » est né au XXe siècle : de l''ornement à la fonction, l''image est devenue une industrie — et un véritable secteur d''emploi. . Pendant des millénaires, l''art et l''artisanat ne font qu''un : le peintre de cathédrale, le mosaïste, l''ébéniste sont des métiers commandés par un pouvoir, une église ou un riche client. La Renaissance invente la perspective (Brunelleschine, Masaccio) et surtout le statut d''artiste-auteur ; les académies (Académie royale de peinture, 1666) hiérarchisent les genres et formalisent l''enseignement du dessin. . L''industrialisation crée le besoin de dessin pour l''objet produit en série : arts industriels au XIXe siècle, puis le Bauhaus (1919) qui réunit art, artisanat et industrie et fait naître la figure du designer. L''école d''Ulm (1953) rationalise, la publicité des années 1960 professionalise le graphisme, et l''effondrement du modernisme des années 1970-1980 ouvre la voie au postmodernisme et à la culture visuelle. . Le numérique accélère tout : photographie puis cinéma (le parlant en 1927, la couleur généralisée dans les années 1950), design graphique, interfaces, motion, puis création générative. Les métiers se diversifient : graphiste, directeur artistique, photographe, monteur, scénographe, designer produit, UX/UI, illustrateur. L''accès se fait par les écoles d''art, les beaux-arts, les BTS design et la formation professionnelle — avec une forte part d''indépendants. . ≈ 36 000 ans — peintures rupestres (Lascaux, 17 000 ans) . Antiquité — canons, mosaïques, sculpture . 1415-1425 — la perspective naît à Florence . 1666 — Académie royale de peinture et de sculpture . 1793 — ouverture du musée du Louvre . 1839 — daguerréotype : la photographie publique . 1919 — Bauhaus . 1927 — premier film parlant (Le Chanteur de jazz) . 1953 — école d''Ulm et design industriel . 1960-1980 — âge d''or de l''affiche et du graphisme . 2000-2020 — design numérique, interfaces, création générative', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '2d20ee0ce7d360ae64a6152f9d103d01') ON CONFLICT (content_hash) DO NOTHING;
INSERT INTO knowledge_documents (title, content, category, country, language, source_url, source_name, source_date, content_hash) VALUES ('Histoire de la psychologie et des métiers du soin psychique', 'La psychologie est née en laboratoire en 1879 et s''est rapidement ouverte aux gens : comprendre le comportement humain est devenu une profession réglementée, entre science, soin et conseil. . Longtemps confiée à la philosophie et à la médecine, la psychologie s''autonomise quand Wilhelm Wundt ouvre à Leipzig en 1879 le premier laboratoire de psychologie expérimentale : on mesure les temps de réaction, les perceptions, la mémoire. En parallèle, la psychiatrie se structure comme spécialité médicale autour de l''asile et de la description des maladies mentales (Esquirol, Pinel) — Pinel libère les aliénés de leurs chaînes en 1793, geste fondateur en France. . Le XXe siècle se divise : le béhaviorisme (Watson, 1913, puis Skinner) ne retient que le comportement observable ; la psychanalyse (Freud, L''Interprétation des rêves, 1900) explore l''inconscient ; puis le cognitivisme des années 1950-1960 réintroduit les processus mentaux, et les neurosciences, enfin, apportent les images du cerveau. En France, la loi du 4 janvier 1985 encadre l''exercice de la psychologie et crée l''Ordre des psychologues. . Aujourd''hui, la psychologie couvre le conseil, la clinique, le travail, l''école, le sport et l''entreprise : psychologue du travail, psychologue scolaire, neuropsychologue, thérapeute de couple, conseiller d''orientation. La formation va de la licence de psychologie (3 ans) au master (5 ans) — seule voie d''accès aux professions réglementées de clinicien ; la psychiatrie, elle, reste une spécialité médicale (études de médecine). . 1793 — Pinel, traitement humain des aliénés à la Salpêtrière . 1879 — premier laboratoire de psychologie (Wilhelm Wundt, Leipzig) . 1900 — Freud, L''Interprétation des rêves . 1913 — béhaviorisme (John Watson) . 1943-1954 — hiérarchie des besoins et humanisme (Maslow) . 1950-1960 — révolution cognitive . 1985 — loi sur l''exercice de la psychologie et Ordre des psychologues . 1990-2020 — neurosciences cognitives et imagerie cérébrale . 2010-2025 — développement des TCC et de la santé mentale au travail', 'histoire', NULL, 'fr', NULL, 'ARCEUS (site)', CURRENT_DATE, '0f22ce22a6848a92403641354b03d0b4') ON CONFLICT (content_hash) DO NOTHING;
